function rotateVec(point, angle) {
  return rotatePt(0.0, 0.0, point.x, point.y, angle);
}

function rotatePt(center_x, center_y, x, y, angle) {
  var radians = (Math.PI / 180) * (angle * (-1.0));
  var sin = Math.sin(radians), cos = Math.cos(radians);
  return [((cos * (x - center_x)) + (sin * (y - center_y)) + center_x), ((cos * (y - center_y)) - (sin * (x - center_x)) + center_y)];
}

function angleVec(point) {
  const vec = createVector(point.x, point.y).normalize();
  return anglePt(0.0, 0.0, vec.x, vec.y);
}

function anglePt(center_x, center_y, x, y) {
  var dx = (center_x - x);
  var dy = (center_y - y);
  var theta = (Math.atan2(-dy, -dx)) * (180 / Math.PI);
  if(theta < 0) {
    theta += 360;
  }

  return theta;
}

function distVec(p1, p2) {
  return distance(p1.x, p1.y, p2.x, p2.y);
}

function distance(x1, y1, x2, y2) {
  var dx = x2 - x1;
  var dy = y2 - y1;
  return Math.sqrt((dx * dx + dy * dy));
}

function difference(p1, p2) {
  return Math.abs(p1 - p2);
}

function setLineDash(dash) {
  drawingContext.setLineDash(dash);
}

function roundToNearestDigit(value, toNearest, fixed) {
  var div = 1.0 / toNearest;
  return (Math.round(value * div) / div).toFixed(fixed);
}


class Queue {

  constructor() {
    this.elements = {};
    this.head = 0;
    this.tail = 0;
  }

  enqueue(element) {
    this.elements[this.tail] = element;
    this.tail++;
  }

  dequeue() {
    if(this.length === 0) {
      return null;
    }
    var item = this.elements[this.head];
    delete this.elements[this.head];
    this.head++;

    return item;
  }

  peek() {
    if(this.length === 0) {
      return null;
    }
    else {
      return this.elements[this.head];
    }
  }

  get length() {
    return this.tail - this.head;
  }

  get isEmpty() {
    return this.length === 0;
  }
}

