var ENTITYTYPE_A = 0;
var ENTITYTYPE_B = 1;
var ENTITYTYPE_C = 2;

var MINDIST = 24.0;
var CONNECTIONDIST = 12.0;
var MAXCONNECTIONDIST = 200.0;
var MAXMINDSIZE = 10;

var MESSAGE_Q_CONNECT = 0;
var MESSAGE_A_YES = 1;
var MESSAGE_A_NO = 2;
var MESSAGE_A_CONNECTED = 3;
var MESSAGE_A_BUSY = 4;
var MESSAGE_M_DISCONNECT;

var MINDINFO_BUSY = 0;
var MINDINFO_NOCONNECTION = 1;
var MINDINFO_STOPPEDPLAYING = 2;


class Entity {

  constructor(id, type) {
    this.id = id;
    this.type = type;
    this.entityObject = null;
  }

  init() {
    this.entityObject.init();
    this.entityCPU = new EntityCPU(this.entityObject);

    var signalType = ENTITYSIGNAL_INIT;
    var signalFunction = ENTITYSIGNAL_FUNCTIONS[signalType];
    var entityObjectSignalObj = new EntityObjectSignalObj(this.entityObject, signalType, signalFunction, Math.round(200 + random(400)), 0.0, 0.0);

    this.entityObject.addSignalObj(entityObjectSignalObj);
  }

  process() {
    this.entityCPU.process();
  }

  setEntityObject(entityObject) {
    this.entityObject = entityObject;
  }

  handleMessageIn(message, senderEntityObject) {
    this.entityCPU.entityMessageProcessor.messageIn(message, senderEntityObject);
  }
}


class EntityCPU {

  constructor(entityObject) {
    this.entityObject = entityObject;
    this.entitySensor = entityObject.entitySensor;

    this.entityMind = new EntityMind(this);
    this.entityMessageProcessor = new EntityMessageProcessor(this.entityObject, this, this.entityMind);
    this.entityBehaviour = new EntityBehaviour(entityObject, this.entityMind, this.entityMessageProcessor);
  }

  process() {
    this.handleSensorEvents();
    this.entityBehaviour.process();
  }

  bump() {
    var entityConnector = this.entityObject.entityConnector;

    if(entityConnector.frontConnector != null) {
      this.disConnect(entityConnector.frontConnector);
    }
    if(entityConnector.backConnector != null) {
      this.disConnect(entityConnector.backConnector);
    }
  }

  disConnect(conntectedEntityObject) {
    this.entityMessageProcessor.messageOut(new EntityMessageObj(MESSAGE_M_DISCONNECT, null), conntectedEntityObject);

    var entityConnector = this.entityObject.entityConnector;
    entityConnector.disConnect(conntectedEntityObject);
  }

  setInactive(value) {
    this.entityBehaviour.inactiveValue = value;
  }

  isInactive() {
    return (this.entityBehaviour.inactiveValue > 0);
  }

  handleSensorEvents() {
    if(!(this.entitySensor.sensorEvents.isEmpty)) {
      var eventObject = this.entitySensor.sensorEvents.dequeue();
      eventObject.executeEventFunction();
    }
  }
}


class EntityMind {

  constructor(entityCPU) {
    this.entityCPU = entityCPU;
    this.mind = [];
  }

  addMindEntry(mindObj) {
    if(this.mind.length > MAXMINDSIZE) {
      this.mind.shift();
    }
    this.mind.push(mindObj);
  }

  getMindInfo(entityObject) {
    var entityObjectId = entityObject.id;

    for(var i=0; i<this.mind.length; i++) {
      var curMindObj = this.mind[i];
      if(curMindObj.entityObjectId == entityObjectId) {
        return curMindObj.mindInfo;
      }
    }

    return null;
  }
}


class EntityMindObj {

  constructor(entityObject, mindInfo) {
    this.entityObjectId = entityObject.id;
    this.mindInfo = mindInfo;
  }
}


class EntityMessageProcessor {

  constructor(entityObject, entityCPU, entityMind) {
    this.entityObject = entityObject;
    this.entityCPU = entityCPU;
    this.entityMind = entityMind;

    this.dialogEntityObject = null;
  }

  messageIn(messageObj, senderEntityObject) {
    var messageCode = messageObj.message;
    var responseToMessageCode = messageObj.responseTo;
    var isInDialog = (this.dialogEntityObject != null);

    switch(messageCode) {
      case MESSAGE_Q_CONNECT: {
        if(isInDialog) {
          this.messageOut(new EntityMessageObj(MESSAGE_A_BUSY, MESSAGE_Q_CONNECT), senderEntityObject);
          return;
        }

        var isBackConnected = this.entityObject.entityConnector.isBackConnected();
        if(isBackConnected) {
          this.messageOut(new EntityMessageObj(MESSAGE_A_NO, MESSAGE_Q_CONNECT), senderEntityObject);
          return;
        }
        else {
          this.dialogEntityObject = senderEntityObject;
          this.messageOut(new EntityMessageObj(MESSAGE_A_YES, MESSAGE_Q_CONNECT), senderEntityObject);
          return;
        }

        break;
      }

      case MESSAGE_A_YES: {
        switch(responseToMessageCode) {
          case MESSAGE_Q_CONNECT: {
            this.entityObject.entityConnector.setFrontConnection(senderEntityObject);
            this.messageOut(new EntityMessageObj(MESSAGE_A_CONNECTED, MESSAGE_A_YES), senderEntityObject);
            this.dialogEntityObject = null;
            return;
          }
        }

        break;
      }

      case MESSAGE_A_NO: {
        switch(responseToMessageCode) {
          case MESSAGE_Q_CONNECT: {
            this.entityMind.addMindEntry(new EntityMindObj(senderEntityObject, MINDINFO_NOCONNECTION));
            this.dialogEntityObject = null;
            return;
          }
        }

        break;
      }

      case MESSAGE_A_CONNECTED: {
        this.entityObject.entityConnector.setBackConnection(senderEntityObject);
        this.dialogEntityObject = null;
        return;
      }

      case MESSAGE_M_DISCONNECT: {
        this.entityObject.entityConnector.disConnect(senderEntityObject);
        this.dialogEntityObject = null;
        this.entityMind.addMindEntry(new EntityMindObj(senderEntityObject, MINDINFO_STOPPEDPLAYING));
        return;
      }

      case MESSAGE_A_BUSY: {
        this.dialogEntityObject = null;
        this.entityMind.addMindEntry(new EntityMindObj(senderEntityObject, MINDINFO_BUSY));
        return;
      }
    }
  }

  messageOut(messageObj, receiverEntityObject) {
    var messageCode = messageObj.message;

    switch(messageCode) {
      case MESSAGE_Q_CONNECT: {
        this.dialogEntityObject = receiverEntityObject;
        break;
      }

      case MESSAGE_M_DISCONNECT: {
        this.dialogEntityObject = null;
        this.entityMind.addMindEntry(new EntityMindObj(receiverEntityObject, MINDINFO_STOPPEDPLAYING));
        break;
      }

      case MESSAGE_A_BUSY: {
        this.dialogEntityObject = null;
        this.entityMind.addMindEntry(new EntityMindObj(receiverEntityObject, MINDINFO_BUSY));
        break;
      }
    }

    this.entityObject.messageOut(messageObj, receiverEntityObject);
  }
}


class EntityMessageObj {

  constructor(message, responseTo) {
    this.message = message;
    this.responseTo = responseTo;
  }
}


class EntityBehaviour {

  constructor(entityObject, entityMind, entityMessageProcessor) {
    this.entityObject = entityObject;
    this.entityMind = entityMind;
    this.entityMessageProcessor = entityMessageProcessor;
    this.entitySensor = entityObject.entitySensor;
    this.inactiveValue = 0;

    this.init();
  }

  init() {
    this.goToVec = createVector(0.0, 0.0);
    this.goAwayVec = createVector(0.0, 0.0);
    this.alignVec = createVector(0.0, 0.0);
    this.resultVec = createVector(0.0, 0.0);

    this.goToCount = 1;
    this.goAwayCount = 1;
    this.alignCount = 1;
  }

  process() {
    this.init();

    if(this.inactiveValue > 0) {
      this.inactiveValue--;
    }
    else {
      this.playWithOthers();
    }
  }

  playWithOthers() {
    var sensorViews = this.entitySensor.sensorView;
    if(sensorViews.length == 0) {
      return;
    }

    sensorViews.forEach((sensorView) => {
      var viewType = sensorView.type;
      var viewDistance = sensorView.distance;

      sensorView.setVectorToViewer(this.entityObject);

      if(sensorView.isInactive) {
        this.goAway(sensorView, viewDistance, 50.0);
      }
      else if(this.entityObject.type == viewType) {
        this.playWithFriends(sensorView);
      }
      else {
        this.reactToOthers(sensorView);
      }

      if(this.entityObject.entityConnector.frontConnector != null) {
        this.reactToFrontConnection(this.entityObject.entityConnector.frontConnector);
      }
    });

    this.setResultVector();
  }

  playWithFriends(sensorView) {
    var viewDistance = sensorView.distance;

    if(viewDistance > MINDIST) {
      this.align(sensorView, viewDistance, 15.0);
      this.goTo(sensorView, viewDistance, 5.0);
    }
    else {
      this.goAway(sensorView, viewDistance, 5.0);
    }

    if((this.entityObject.isConnectable()) && (viewDistance <= CONNECTIONDIST)) {
      var mindInfo = this.entityMind.getMindInfo(sensorView.entityObject);
      var dialogEntityObject = this.entityMessageProcessor.dialogEntityObject;
      if((mindInfo == null) && (dialogEntityObject != sensorView.entityObject)) {
        this.askForConnection(sensorView);
      }
    }
  }

  askForConnection(sensorView) {
    this.entityMessageProcessor.messageOut(new EntityMessageObj(MESSAGE_Q_CONNECT, null), sensorView.entityObject);
  }

  reactToOthers(sensorView) {
    var viewDistance = sensorView.distance;
    var isConnected = this.entityObject.entityConnector.isConnected();
    if(isConnected) {
      this.goAway(sensorView, viewDistance, 50.0);
    }
    else {
      this.goAway(sensorView, viewDistance, 25.0);
    }
  }

  reactToFrontConnection(frontConnection) {
    var frontConnection = this.entityObject.entityConnector.frontConnector;
    var frontConnectionDistance =  distVec(this.entityObject.position, frontConnection.position);

    var connectionViewObj = new EntitySensorViewObj(frontConnection, frontConnection.type, frontConnectionDistance);
    connectionViewObj.setVectorToViewer(this.entityObject);

    if(frontConnectionDistance > MINDIST) {
      this.align(connectionViewObj, frontConnectionDistance, 35.0);
      this.goTo(connectionViewObj, frontConnectionDistance, 35.0);
    }
    else {
      this.goAway(connectionViewObj, frontConnectionDistance, 10.0);
    }
  }

  goTo(sensorView, distance, weightFactor) {
    var goToViewVec = createVector(sensorView.vectorToViewer.x, sensorView.vectorToViewer.y);
    goToViewVec.normalize();
    goToViewVec.div(distance);
    goToViewVec.mult(weightFactor);

    this.goToVec.add(goToViewVec);
    this.goToCount++;
  }

  goAway(sensorView, distance, weightFactor) {
    var position = this.entityObject.position;
    var goAwayViewVec = createVector(position.x, position.y);
    goAwayViewVec.sub(sensorView.entityObject.position);
    goAwayViewVec.normalize();
    goAwayViewVec.div(distance);
    goAwayViewVec.mult(weightFactor);

    this.goAwayVec.add(goAwayViewVec);
    this.goAwayCount++;
  }

  align(sensorView, distance, weightFactor) {
    this.alignVec.add(sensorView.entityObject.direction);
    this.alignVec.mult(weightFactor);
    this.alignCount++;
  }

  setResultVector() {
    this.goToVec.div(this.goToCount);
    this.goAwayVec.div(this.goAwayCount);
    this.alignVec.div(this.alignCount);

    this.resultVec.add(this.goToVec);
    this.resultVec.add(this.goAwayVec);
    this.resultVec.normalize();

    this.alignVec.normalize();
    this.alignVec.mult(0.5);

    this.resultVec.add(this.alignVec);
    this.resultVec.normalize();

    this.entityObject.addResultVector(this.resultVec);
  }
}

