var ENTITYSIZE = 8;

var MAXSPEED = 0.35;
var INCSPEED = 0.005;
var DELTADIV_DIRECTOR = 20.0;
var DELTADIV_VIEWCONTAINER = 60.0;


class EntityObject {

  constructor(fieldObject, entity, id, type, position, direction, colorFill, connectionStroke) {
    this.fieldObject = fieldObject;
    this.entity = entity;
    this.id = id;
    this.type = type;
    this.position = position;
    this.direction = direction;
    this.colorFill = colorFill;
    this.connectionStroke = connectionStroke;

    this.alpha = 0.0;
    this.fieldIndex = -1;
    this.isAbleToConnect = false;

    if(DEBUG) {
      this.debugResetColorFill = colorFill;
    }
  }

  init() {
    this.entityObjectSignalProcessor = new EntityObjectSignalProcessor(this);
    this.entityDirector = new EntityDirector(this, this.direction);
    this.entityConnector = new EntityConnector(this);
    this.entitySensor = new EntitySensor(this, this.fieldObject);
    this.entitySensorViewContainer = new EntitySensorViewContainer(this, this.entitySensor);
  }

  process() {
    this.entitySensorViewContainer.process();
    this.entityDirector.process();
    this.entityConnector.process();
  }

  bump() {
    this.entity.entityCPU.bump();
  }

  disConnect(conntectedEntityObject) {
    this.entity.entityCPU.disConnect(conntectedEntityObject);
  }

  getTopBottomLeftRightBounds() {
    var halfSize = (ENTITYSIZE / 2.0);
    return[this.position.y - halfSize, this.position.y + halfSize, this.position.x - halfSize, this.position.x + halfSize];
  }

  getDirectionVector() {
    return this.entityDirector.direction;
  }

  setSpeed(speed) {
    this.entityDirector.speed = speed;
  }

  setTargetVector(targetVector) {
    targetVector.setMag(32);
    this.entityDirector.targetVector = targetVector;
  }

  setInactive(value) {
    this.entity.entityCPU.setInactive(value);
  }

  isInactive() {
    return (this.entity.entityCPU.isInactive());
  }

  isConnectable() {
    return ((this.isAbleToConnect) && (this.entityConnector.isConnectable()));
  }

  addResultVector(resultVector) {
    var targetVec = this.entityDirector.targetVector;
    targetVec.add(resultVector);
    targetVec.setMag(32);
  }

  addSignalObj(signalObj) {
     this.entityObjectSignalProcessor.addSignalObj(signalObj);
  }

  addSensorEventObj(eventObject) {
    this.entitySensor.addSensorEventObj(eventObject);
  }

  messageIn(message, senderEntityObject) {
    this.entity.handleMessageIn(message, senderEntityObject);
  }

  messageOut(message, receiverEntityObject) {
    receiverEntityObject.messageIn(message, this);
  }

  draw() {
    this.entityObjectSignalProcessor.draw();
    this.entityDirector.draw();

    stroke(35, 35, 35, (255.0 * this.alpha));
    strokeWeight(2.5);

    if(DEBUG && (this.debugIndex != undefined)) {
      var debugColor = DEBUG_ENTITY_COLORS[this.debugIndex];
      fill(red(debugColor), green(debugColor), blue(debugColor), 255.0);
    }
    else {
      fill(red(this.colorFill), green(this.colorFill), blue(this.colorFill), (100.0 * this.alpha));
    }

    circle(this.position.x, this.position.y, ENTITYSIZE);

    if(DEBUG && (this.debugIndex != undefined)) {
      this.drawDebugBehaviourVectors();
    }

    if(this.debugResetColorFill != undefined) {
      this.colorFill = this.debugResetColorFill;
    }
  }

  drawDebugBehaviourVectors() {
    var entityBehaviour = this.entity.entityCPU.entityBehaviour;

    var goToVec_GREEN = entityBehaviour.goToVec;
    var goAwayVec_RED = entityBehaviour.goAwayVec;
    var alignVec_YELLOW = entityBehaviour.alignVec;
    var resultVec_BLUE = entityBehaviour.resultVec;

    drawDebugVector(this, goToVec_GREEN, color(0, 255, 0));
    drawDebugVector(this, goAwayVec_RED, color(255, 0,0));
    drawDebugVector(this, alignVec_YELLOW, color(255, 255, 0));
    drawDebugVector(this, resultVec_BLUE, color(0, 0, 255));

    function drawDebugVector(entityObject, vector, colorValue) {
      var x = entityObject.position.x;
      var y = entityObject.position.y;

      var directionVector = createVector(vector.x, vector.y);
      directionVector.setMag(32);

      stroke(colorValue);
      strokeWeight(1.5);
      line(x, y, (x + directionVector.x), (y + directionVector.y));
      fill(colorValue);
      circle((x + directionVector.x), (y + directionVector.y), 4);
    }
  }
}


class EntityObjectSignalProcessor {

  constructor(entityObject) {
    this.entityObject = entityObject;
    this.entityObjectSignals = [];
  }

  addSignalObj(signalObj) {
    this.entityObjectSignals.push(signalObj);
  }

  draw() {
    var validEntityObjectSignals = [];
    this.entityObjectSignals.forEach((signalObj) => {
      signalObj.draw();

      if(!signalObj.isDeletable) {
        validEntityObjectSignals.push(signalObj);
      }
    });

    this.entityObjectSignals = validEntityObjectSignals;
  }
}


class EntityObjectSignalObj {

  constructor(entityObject, signalType, signalFunction, duration, minValue, maxValue) {
    this.entityObject = entityObject;
    this.signalType = signalType;
    this.signalFunction = signalFunction;
    this.step = (1.0 / duration);
    this.minValue = minValue;
    this.maxValue = maxValue;
    this.curValue = 0.0;
    this.signalOut = true;

    this.isDeletable = false;
  }

  draw() {
    this.signalFunction(this);
  }
}


class EntityDirector {

  constructor(entityObject, direction) {
    this.entityObject = entityObject;
    this.position = entityObject.position;
    this.direction = direction;
    this.targetVector = direction;

    this.directionAngle = 0.0;
    this.speed = 0.0;
  }

  process() {
    this.directionAngle = angleVec(this.direction);

    if(this.speed < MAXSPEED) {
      this.speed += INCSPEED;
    }

    this.adjustDirectionToTargetVector();

    var stepVector = createVector(this.direction.x, this.direction.y);
    stepVector.limit(this.speed);

    this.position.add(stepVector.x, stepVector.y);
  }

  adjustDirectionToTargetVector() {
    var angleToTarget = angleVec(this.targetVector);
    var angleDiff = difference(this.directionAngle, angleToTarget);
    var rotAngle = (angleDiff > 135.0) ? 8.0 : (angleDiff > 90.0) ? 6.0 : (angleDiff > 45.0) ? 4.0 : 2.0;

    if(angleDiff > 2.0) {
      var rotationAngle = ((this.directionAngle - angleToTarget + 360) % 360 > 180) ? rotAngle : -(rotAngle);
      var rotatedDirection = rotateVec(this.direction, rotationAngle);

      this.direction.set(rotatedDirection[0], rotatedDirection[1]);
    }
  }

  setDirection(newDirection) {
    this.direction.set(newDirection.x, newDirection.y);
  }

  draw() {
    var x = this.entityObject.position.x;
    var y = this.entityObject.position.y;

    var alpha = (255.0 * this.entityObject.alpha);
    var direction = this.entityObject.entityDirector.direction;

    var startVector = createVector(direction.x, direction.y);
    var directionVector = createVector(direction.x, direction.y);
    startVector.limit(ENTITYSIZE / 2.0);
    directionVector.limit(ENTITYSIZE * 2.0);

    stroke(255, 153, 0, alpha);
    strokeWeight(0.5);
    line((x + startVector.x), (y + startVector.y), (x + directionVector.x), (y + directionVector.y));
    fill(255, 153, 0, alpha);
    circle((x + directionVector.x), (y + directionVector.y), 2);
  }
}


class EntityConnector {

  constructor(entityObject) {
    this.entityObject = entityObject;

    this.frontConnector = null;
    this.frontConnectorPosition = null;
    this.backConnector = null;
    this.connectionSignal = null;
  }

  process() {
    if(this.frontConnector == null) {
      return;
    }

    var delta_x = difference(this.entityObject.position.x, this.frontConnectorPosition.x);
    var delta_y = difference(this.entityObject.position.y, this.frontConnectorPosition.y);

    if((delta_x > MAXCONNECTIONDIST) || (delta_y > MAXCONNECTIONDIST)) {
      this.entityObject.disConnect(this.frontConnector);
    }
  }

  isConnectable() {
    return (this.frontConnector == null);
  }

  isBackConnected() {
    return (this.backConnector != null);
  }

  isConnected() {
    return ((this.frontConnector == null) || (this.backConnector != null) || (this.frontConnectorPosition != null));
  }

  setFrontConnection(conntectedEntityObject) {
    this.frontConnector = conntectedEntityObject;
    this.frontConnectorPosition = conntectedEntityObject.position;
    this.setOnConnectionSignal();

    var signalType = ENTITYSIGNAL_CONNECTION;
    var signalFunction = ENTITYSIGNAL_FUNCTIONS[signalType];
    this.connectionSignal = new EntityObjectSignalObj(this.entityObject, signalType, signalFunction, 35, 0.0, 0.0);
  }

  setBackConnection(conntectedEntityObject) {
    this.backConnector = conntectedEntityObject;
    this.setOnConnectionSignal();
  }

  setOnConnectionSignal() {
    var signalType = ENTITYSIGNAL_ONCONNECTDISCONNECT;
    var signalFunction = ENTITYSIGNAL_FUNCTIONS[signalType];
    var entityObjectSignalObj = new EntityObjectSignalObj(this.entityObject, signalType, signalFunction, 200, 0.0, 0.0);

    this.entityObject.addSignalObj(entityObjectSignalObj);
  }

  disConnect(conntectedEntityObject) {
    if(conntectedEntityObject == this.frontConnector) {
      this.frontConnector = null;
    }
    else if(conntectedEntityObject == this.backConnector) {
      this.backConnector = null;
    }
  }

  draw() {
    if(this.connectionSignal == null) {
      return;
    }

    this.connectionSignal.draw();

    if(this.connectionSignal.isDeletable) {
      this.connectionSignal = null;
    }
  }
}


class EntitySensor {

  constructor(entityObject, fieldObject) {
