    this.fieldObject = fieldObject;
    this.sensorView = [];
    this.sensorEvents = null;
    this.init();
  }

  init() {
    this.sensorEvents = new Queue();
  }

  addSensorEventObj(eventObject) {
    this.sensorEvents.enqueue(eventObject);
  }
}


class EntitySensorViewObj {

  constructor(entityObject, type, distance) {
    this.entityObject = entityObject;
    this.type = type;
    this.distance = distance;
    this.isInactive = entityObject.isInactive();

    this.vectorToViewer = createVector(this.entityObject.position.x, this.entityObject.position.y);
  }

  setVectorToViewer(viewerEntityObject) {
    this.vectorToViewer = createVector(this.entityObject.position.x, this.entityObject.position.y);
