    this.eventFunction = eventFunction;
    this.eventObjects = [];
  }

  executeEventFunction() {
    return this.eventFunction(this.eventObjects);
  }
}


class EntitySensorViewContainer {

  constructor(entityObject, entitySensor) {
    this.entityObject = entityObject;
    this.position = entityObject.position;
    this.entitySensor = entitySensor;
    this.init();
  }

  init() {
    this.topLeft = createVector(this.position.x, this.position.y);
    this.bottomRight = createVector(this.position.x, this.position.y);
  }

  process() {
    var sensorView = this.entitySensor.sensorView;
    if(sensorView.length == 0) {
      return;
    }

    var minX = 1000.0;
    var maxX = -1000.0
    var minY = 1000.0;
    var maxY = -1000.0

    sensorView.forEach((viewObject) => {
      var curViewObjectPosition = viewObject.entityObject.position;

      minX = (curViewObjectPosition.x < minX) ? curViewObjectPosition.x : minX;
      maxX = (curViewObjectPosition.x > maxX) ? curViewObjectPosition.x : maxX;
      minY = (curViewObjectPosition.y < minY) ? curViewObjectPosition.y : minY;
      maxY = (curViewObjectPosition.y > maxY) ? curViewObjectPosition.y : maxY;
    });

    var minX_delta = (difference(this.topLeft.x, minX) / DELTADIV_VIEWCONTAINER);
    var maxX_delta = (difference(this.bottomRight.x, maxX) / DELTADIV_VIEWCONTAINER);
    var minY_delta = (difference(this.topLeft.y, minY) / DELTADIV_VIEWCONTAINER);
    var maxY_delta = (difference(this.bottomRight.y, maxY) / DELTADIV_VIEWCONTAINER);

    this.topLeft.x = (this.topLeft.x < minX) ? (this.topLeft.x += minX_delta) : (this.topLeft.x -= minX_delta);
    this.topLeft.y = (this.topLeft.y < minY) ? (this.topLeft.y += minY_delta) : (this.topLeft.y -= minY_delta);
    this.bottomRight.x = (this.bottomRight.x < maxX) ? (this.bottomRight.x += maxX_delta) : (this.bottomRight.x -= maxX_delta);
    this.bottomRight.y = (this.bottomRight.y < maxY) ? (this.bottomRight.y += maxY_delta) : (this.bottomRight.y -= maxY_delta);
  }

  draw() {
    var entityColor = this.entityObject.colorFill;
    var alpha = this.entityObject.alpha;

    if(DEBUG && (this.entityObject.debugIndex != undefined)) {
      fill(255, 0, 0, 35);
    }
    else {
      noFill();
    }
    strokeWeight(1.0);
    stroke(red(entityColor), green(entityColor), blue(entityColor), (12.0 * alpha));

    beginShape();
      curveVertex(this.topLeft.x, this.topLeft.y);
      curveVertex(this.bottomRight.x, this.topLeft.y);
      curveVertex(this.bottomRight.x, this.bottomRight.y);
      curveVertex(this.topLeft.x, this.bottomRight.y);
      curveVertex(this.topLeft.x, this.topLeft.y);
      curveVertex(this.bottomRight.x, this.topLeft.y);
      curveVertex(this.bottomRight.x, this.bottomRight.y);
    endShape();
  }
}

