class Field {

  constructor(canvasArea, fieldArea, fieldBkGr, delta_x, delta_y) {
    this.entities = [];
    this.fieldObject = null;

    this.init(canvasArea, fieldArea, fieldBkGr, delta_x, delta_y);
  }

  init(canvasArea, fieldArea, fieldBkGr, delta_x, delta_y) {
    this.fieldObject = new FieldObject(canvasArea, fieldArea, fieldBkGr, delta_x, delta_y);

    for(var i=0; i<ENTITIES; i++) {
      var entity = this.createEntity(i);

      this.entities.push(entity);
      this.createEntityObject(entity, canvasArea, fieldArea, delta_x, delta_y);

      entity.init();

      if(DEBUG) {
        var debugIndex = this.getDebugIndex(entity);
        if(debugIndex != -1) {
          entity.debugIndex = debugIndex;
          entity.entityObject.debugIndex = debugIndex;
        }
      }
    }
  }

  process() {
    this.entities.forEach((curEntity) => {
      curEntity.process();
    });

     this.fieldObject.process();
  }

  createEntity(id) {
    var type = (Math.ceil(random(30) / 10.0)) - 1;
    return new Entity(id, type);
  }

  createEntityObject(entity, canvasArea, fieldArea, delta_x, delta_y) {
    var id = entity.id;
    var type = entity.type;
    var entityObject = this.fieldObject.createEntityObject(entity, id, type, canvasArea, fieldArea, delta_x, delta_y);

    entity.setEntityObject(entityObject);
  }

  getDebugIndex(entity) {
    for(var i=0; i<DEBUG_ENTITY_IDS.length; i++) {
      var debug_id = DEBUG_ENTITY_IDS[i];
      if(entity.id == debug_id) {
        return i;
      }
    }

    return -1;
  }

  draw() {
    this.fieldObject.draw();
  }
}

// === Tab: FieldObject ===


var HALFENTITYOBJECTVIEWSIZE = 25;
var MAXVIEWRADIUS = 50;


class FieldObject {

  constructor(canvasArea, fieldArea, img, delta_x, delta_y) {
    this.entityObjects = [];
    this.fieldObjects = [];

    this.fieldTop = ((canvasArea[1] - fieldArea[1]) / 2.0) + delta_y;
    this.fieldBottom = (this.fieldTop + fieldArea[1]) + delta_y;
    this.fieldLeft = ((canvasArea[0] - fieldArea[0]) / 2.0) + delta_x;
    this.fieldRight = (this.fieldLeft + fieldArea[0]) + delta_x;

    this.img = img;
  }

  process() {
    this.entityObjects.sort((a,b) => a.position.x - b.position.x);

    var fieldIndex = 0;

    this.entityObjects.forEach((curEntityObject) => {
      curEntityObject.fieldIndex = fieldIndex;

      this.setEntityObjectView(curEntityObject);
      this.checkFieldBounds(curEntityObject);

      curEntityObject.process();

      fieldIndex++;
    });
  }

  createEntityObject(entity, id, type, canvasArea, fieldArea, delta_x, delta_y) {
    var entityArea_x = (fieldArea[0] - 50);
    var entityArea_y = (fieldArea[1] - 50);

    var xValue = (random(entityArea_x) + ((canvasArea[0] - fieldArea[0]) / 2.0)) + 25 + delta_x;
    var yValue = (random(entityArea_y) + ((canvasArea[1] - fieldArea[1]) / 2.0)) + 25 + delta_y;
    var position = createVector(xValue, yValue);

    var xDirection = (random(entityArea_x) - (entityArea_x / 2.0));
    var yDirection = (random(entityArea_y) - (entityArea_y / 2.0));

    var direction = createVector(xDirection, yDirection);
    direction.setMag(ENTITYSIZE * 2.0);

    var colorFill = [color(255, 255, 255, 100), color(150, 150, 150, 100), color(0, 0, 0, 100)];
    var connectionStroke = [color(220, 220, 220, 255), color(140, 140, 140, 255), color(0, 0, 0, 255)];
    var entityObject = new EntityObject(this, entity, id, type, position, direction, colorFill[type], connectionStroke[type]);

    this.entityObjects.push(entityObject);
    this.fieldObjects.push(entityObject);

    return entityObject;
  }

  checkFieldBounds(entityObject) {
    var directionVector = entityObject.getDirectionVector();
    var reflectionVector = createVector(0.0, 0.0);

    var topBottomLeftRightBounds = entityObject.getTopBottomLeftRightBounds();

    var boundTop = topBottomLeftRightBounds[0];
    var boundBottom = topBottomLeftRightBounds[1];
    var boundLeft = topBottomLeftRightBounds[2];
    var boundRight = topBottomLeftRightBounds[3];

    var boundHit = false;

    if((boundTop < this.fieldTop)) {
      entityObject.position.y += 1.5;
      entityObject.setSpeed(0.0);
      reflectionVector.y = 1.0;
      boundHit = true;
    }
    else if((boundBottom > this.fieldBottom)) {
      entityObject.position.y -= 1.5;
      entityObject.setSpeed(0.0);
      reflectionVector.y = (-1.0);
      boundHit = true;
    }

    if((boundLeft < this.fieldLeft)) {
      entityObject.position.x += 1.5;
      entityObject.setSpeed(0.0);
      reflectionVector.x = 1.0;
      boundHit = true;
    }
    else if((boundRight > this.fieldRight)) {
      entityObject.position.x -= 1.5;
      entityObject.setSpeed(0.0);
      reflectionVector.x = (-1.0);
      boundHit = true;
    }

    if(boundHit) {
      var eventType = ENTITYSENSOREVENT_FIELDBOUNDS;
      var eventFunction = ENTITYSENSOREVENT_FUNCTIONS[eventType];

      var entitySensorEventObj = new EntitySensorEventObj(eventType, eventFunction);
      entitySensorEventObj.eventObjects.push(entityObject);
      entitySensorEventObj.eventObjects.push(reflectionVector);

      entityObject.addSensorEventObj(entitySensorEventObj);

      var signalType = ENTITYSIGNAL_HITBOUNDS;
      var signalFunction = ENTITYSIGNAL_FUNCTIONS[signalType];
      var entityObjectSignalObj = new EntityObjectSignalObj(entityObject, signalType, signalFunction, 20, 0.0, (ENTITYSIZE * 2.5));

      entityObject.addSignalObj(entityObjectSignalObj);

      var inactiveValue = Math.round(random(50, 100));
      entityObject.setInactive(inactiveValue);
    }
  }

  setEntityObjectView(entityObject) {
    var sensorView = entityObject.entitySensor.sensorView;
    var entityPos = entityObject.fieldIndex;

    var viewLeft = [];
    var viewRight = [];
    var viewLeftStart, viewLeftEnd, viewRightStart, viewRightEnd = -1;

    if(entityPos > 0) {
      viewLeftStart = (entityPos - HALFENTITYOBJECTVIEWSIZE);
      viewLeftStart = (viewLeftStart < 0) ? 0 : viewLeftStart;
    }
    viewLeftEnd = entityPos;

    if(entityPos < (ENTITIES - 1)) {
      viewRightStart = (entityPos + 1);
    }
    viewRightEnd = (viewRightStart + HALFENTITYOBJECTVIEWSIZE);
    viewRightEnd = (viewRightEnd > ENTITIES) ? ENTITIES : viewRightEnd;

    sensorView.length = 0;

    if(viewLeftStart != -1) {
      viewLeft = this.entityObjects.slice(viewLeftStart, viewLeftEnd);
      viewLeft.reverse();
      this.getEntityObjectSensorView(viewLeft, entityObject, sensorView);
    }

    if(viewRightStart != -1) {
      viewRight = this.entityObjects.slice(viewRightStart, viewRightEnd);
      this.getEntityObjectSensorView(viewRight, entityObject, sensorView);
    }

    sensorView.sort((a,b) => a.distance - b.distance);

    if(DEBUG && (entityObject.debugIndex != undefined)) {
      this.markEntityObjectSensorView(entityObject, sensorView);
    }
  }

  getEntityObjectSensorView(view, entityObject, sensorView) {
    var viewLength = view.length;
    if(viewLength == 0) {
      return;
    }

    for(var i=0; i<viewLength; i++) {
      var nextEntityObject = view[i];
      var orthoDistance = difference(entityObject.position.x, nextEntityObject.position.x);
      if(orthoDistance > MAXVIEWRADIUS) {
        break;
      }

      var distance = distVec(entityObject.position, nextEntityObject.position);
      if(distance > MAXVIEWRADIUS) {
        continue;
      }

      var entitySensorViewObj = new EntitySensorViewObj(nextEntityObject, nextEntityObject.type, distance);
      sensorView.push(entitySensorViewObj);
    }
  }

  markEntityObjectSensorView(entityObject, sensorView) {
    var debugIndex = entityObject.debugIndex;
    var debugColor = DEBUG_ENTITY_VIEWCOLORS[debugIndex];

    sensorView.forEach((view) => {
      view.entityObject.colorFill = debugColor;
    });
  }

  draw() {
    image(this.img, 0, 0);

    this.fieldObjects.forEach((curFieldObject) => {
      curFieldObject.entitySensorViewContainer.draw();
    });

    this.fieldObjects.forEach((curFieldObject) => {
      curFieldObject.entityConnector.draw();
    });

    this.fieldObjects.forEach((curFieldObject) => {
      curFieldObject.draw();
    });
  }
}

// === Tab: Functions ===

var ENTITYSENSOREVENT_FIELDBOUNDS = 0;

var ENTITYSENSOREVENT_FUNCTIONS = [

    function(eventObjects) {
      var entityObject = eventObjects[0];
      var reflectionVector = eventObjects[1];

      entityObject.setTargetVector(reflectionVector);
      entityObject.bump();
    }

];

var ENTITYSIGNAL_INIT = 0;
var ENTITYSIGNAL_HITBOUNDS = 1;
var ENTITYSIGNAL_ONCONNECTDISCONNECT = 2;
var ENTITYSIGNAL_CONNECTION = 3;

var ENTITYSIGNAL_FUNCTIONS = [

    function(entityObjectSignalObj) {
      function easeInOutCirc(x) {
        return x < 0.5 ? (1 - Math.sqrt(1 - Math.pow(2 * x, 2))) / 2 : (Math.sqrt(1 - Math.pow(-2 * x + 2, 2)) + 1) / 2;
      }

      var entityObject = entityObjectSignalObj.entityObject;
      entityObjectSignalObj.curValue += entityObjectSignalObj.step;
      if(entityObjectSignalObj.curValue > 1.0) {
          entityObject.alpha = 1.0;
          entityObject.isAbleToConnect = true;
          entityObjectSignalObj.isDeletable = true;
      }

      var signalValue = easeInOutCirc(entityObjectSignalObj.curValue);
      entityObject.alpha = signalValue;
    },


    function(entityObjectSignalObj) {
      function easeInOutQuad(x) {
        return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;  
      }

      if(entityObjectSignalObj.signalOut) {
        entityObjectSignalObj.curValue += entityObjectSignalObj.step;
        if(entityObjectSignalObj.curValue > 1.0) {
          entityObjectSignalObj.curValue = 1.0;
          entityObjectSignalObj.signalOut = false;
        }
      }
      else {
        entityObjectSignalObj.curValue -= entityObjectSignalObj.step;
        if(entityObjectSignalObj.curValue < 0.0) {
          entityObjectSignalObj.curValue = 0.0;
          entityObjectSignalObj.isDeletable = true;
        }
      }

      var signalValue = easeInOutQuad(entityObjectSignalObj.curValue);
      var signalSize = (signalValue * entityObjectSignalObj.maxValue);
      var signalAlpha = (signalValue * 150.0) * (entityObjectSignalObj.entityObject.alpha);

      var entityObjectPosition = entityObjectSignalObj.entityObject.position;

      noStroke();
      fill(255, 0, 0, signalAlpha);
      circle(entityObjectPosition.x, entityObjectPosition.y, signalSize);
    },


    function(entityObjectSignalObj) {
      function easeInQuint(x) {
        return x * x * x * x * x;
      }

      var entityObject = entityObjectSignalObj.entityObject;
      entityObjectSignalObj.curValue += entityObjectSignalObj.step;
      if(entityObjectSignalObj.curValue > 1.0) {
        entityObjectSignalObj.curValue = 1.0;
        entityObjectSignalObj.isDeletable = true;
      }

      var signalValue = easeInQuint(entityObjectSignalObj.curValue);
      var signalSize = (ENTITYSIZE * 4) * signalValue;
      var signalStrokeWeight = (ENTITYSIZE / 2.0);
      var signalAlpha = (255 - (255 * signalValue));

      noFill();
      strokeWeight(signalStrokeWeight);
      stroke(0, 0, 0, signalAlpha);

      circle(entityObject.position.x, entityObject.position.y, signalSize);
    },


    function(entityObjectSignalObj) {
      function easeInOutSine(x) {
        return -(Math.cos(Math.PI * x) - 1) / 2;
      }

      var entityObject = entityObjectSignalObj.entityObject;
      var entityObjectConnector = entityObject.entityConnector;
      var frontConnection = entityObjectConnector.frontConnector;
      var frontConnectorPosition = entityObjectConnector.frontConnectorPosition;
      var connectionStroke = entityObject.connectionStroke;

      if(frontConnection == null) {
        entityObjectSignalObj.signalOut = false;
      }

      if(entityObjectSignalObj.signalOut) {
        entityObjectSignalObj.curValue += entityObjectSignalObj.step;
        if(entityObjectSignalObj.curValue > 1.0) {
          entityObjectSignalObj.curValue = 1.0;
        }
      }
      else {
        entityObjectSignalObj.curValue -= entityObjectSignalObj.step;
        if(entityObjectSignalObj.curValue < 0.0) {
          entityObjectSignalObj.curValue = 0.0;
          frontConnectorPosition = null;
          entityObjectSignalObj.isDeletable = true;
        }
      }

      var signalValue = easeInOutSine(entityObjectSignalObj.curValue);
      var signalAlpha = (255.0 * signalValue);

      if(frontConnectorPosition != null) {
        setLineDash([5, 5]);
        strokeWeight(0.75);
        stroke(red(connectionStroke), green(connectionStroke), blue(connectionStroke), signalAlpha);
        line(entityObject.position.x, entityObject.position.y, frontConnectorPosition.x, frontConnectorPosition.y);
        setLineDash([]);
      }
    }

];

